se four?", "clues": ["Home", "Team", "Paper", "Net"], "correct_connection": "Words that can come before WORK", "distractors": ["Words that follow RAIN", "Musical tempo markings", "Names of chess pieces"], "explanation": "Homework, teamwork, paperwork and network are compound words ending in work."}, {"external_key": "discovery-20260929-line-compounds", "category": "language", "prompt": "What connects these four?", "clues": ["Head", "Dead", "Out", "Under"], "correct_connection": "Words that can come before LINE", "distractors": ["Four compass directions", "Words that follow SNOW", "Names of planets"], "explanation": "Headline, deadline, outline and underline all end in line."}, {"external_key": "discovery-20260929-air-compounds", "category": "language", "prompt": "What connects these four?", "clues": ["Port", "Craft", "Mail", "Field"], "correct_connection": "Words that can follow AIR", "distractors": ["Words that follow SNOW", "Parts of a flower", "Types of triangle"], "explanation": "Airport, aircraft, airmail and airfield all begin with air."}, {"external_key": "discovery-20260929-rain-compounds", "category": "language", "prompt": "What connects these four?", "clues": ["Bow", "Coat", "Drop", "Forest"], "correct_connection": "Words that can follow RAIN", "distractors": ["Words that follow BOOK", "Types of metal", "Parts of a bicycle"], "explanation": "Rainbow, raincoat, raindrop and rainforest all begin with rain."}, {"external_key": "discovery-20260929-snow-compounds", "category": "language", "prompt": "What connects these four?", "clues": ["Man", "Ball", "Flake", "Fall"], "correct_connection": "Words that can follow SNOW", "distractors": ["Names of geometric solids", "Words that follow AIR", "Units of time"], "explanation": "Snowman, snowball, snowflake and snowfall all begin with snow."}, {"external_key": "discovery-20260929-water-compounds", "category": "language", "prompt": "What connects these four?", "clues": ["Fall", "Proof", "Colour", "Melon"], "correct_connection": "Words that can follow WATER", "distractors": ["Words that follow BOOK", "Names of chess moves", "Types of triangle"], "explanation": "Waterfall, waterproof, watercolour and watermelon all begin with water. Watercolour uses British spelling."}, {"external_key": "discovery-20260929-small-primes", "category": "math", "prompt": "What connects these four?", "clues": ["2", "3", "5", "7"], "correct_connection": "The first four prime numbers", "distractors": ["The first four square numbers", "Four multiples of three", "Four composite numbers"], "explanation": "Each number has exactly two positive divisors: 1 and itself. Two is the only even prime number."}, {"external_key": "discovery-20260929-square-values", "category": "math", "prompt": "What connects these four?", "clues": ["4", "9", "16", "25"], "correct_connection": "Squares of consecutive integers from 2 to 5", "distractors": ["Consecutive prime numbers", "Cubes from 2 to 5", "Multiples of six"], "explanation": "They are 2 × 2, 3 × 3, 4 × 4 and 5 × 5."}, {"external_key": "discovery-20260929-cube-values", "category": "math", "prompt": "What connects these four?", "clues": ["8", "27", "64", "125"], "correct_connection": "Cubes of consecutive integers from 2 to 5", "distractors": ["The first four primes", "Multiples of ten", "Squares from 2 to 5"], "explanation": "They are 2 cubed, 3 cubed, 4 cubed and 5 cubed: each number is multiplied by itself twice."}, {"external_key": "discovery-20260929-triangular-values", "category": "math", "prompt": "What connects these four?", "clues": ["1", "3", "6", "10"], "correct_connection": "The first four triangular numbers", "distractors": ["Four even numbers", "Powers of three", "Four prime numbers"], "explanation": "Add the next counting number each time: 1, then 1 + 2, then 1 + 2 + 3, then 1 + 2 + 3 + 4."}, {"external_key": "discovery-20260929-powers-two", "category": "math", "prompt": "What connects these four?", "clues": ["1", "2", "4", "8"], "correct_connection": "The first four nonnegative integer powers of 2", "distractors": ["Four prime numbers", "Multiples of three", "Squares from 1 to 4"], "explanation": "The numbers are 2 to the powers 0, 1, 2 and 3. Starting at 1, double each time."}, {"external_key": "discovery-20260929-multiples-fifteen", "category": "math", "prompt": "What connects these four?", "clues": ["15", "30", "45", "60"], "correct_connection": "The first four positive multiples of 15", "distractors": ["Four square numbers", "Consecutive prime numbers", "Powers of five"], "explanation": "Multiplying 15 by 1, 2, 3 and 4 produces these four values."}, {"external_key": "discovery-20260929-solid-shapes", "category": "math", "prompt": "What connects these four?", "clues": ["Sphere", "Cube", "Cone", "Cylinder"], "correct_connection": "Three-dimensional geometric shapes", "distractors": ["Types of triangle", "Two-dimensional polygons", "Units of length"], "explanation": "Each name describes a solid shape with three dimensions. A circle, by contrast, is two-dimensional."}, {"external_key": "discovery-20260929-polygons-three-six", "category": "math", "prompt": "What connects these four?", "clues": ["Triangle", "Square", "Pentagon", "Hexagon"], "correct_connection": "Polygons with 3, 4, 5 and 6 sides", "distractors": ["Three-dimensional solids", "Shapes with curved boundaries", "Names of angles"], "explanation": "Their numbers of straight sides increase from three to six. A square is a particular four-sided polygon."}, {"external_key": "discovery-20260929-palindrome-words", "category": "language", "prompt": "What connects these four?", "clues": ["Radar", "Level", "Civic", "Refer"], "correct_connection": "Words that read the same backwards", "distractors": ["Words with a silent initial K", "Names of rivers", "Words that all rhyme"], "explanation": "Ignoring capitalisation, reversing the letters of each word leaves the same word. Such words are palindromes."}, {"external_key": "discovery-20260929-silent-k", "category": "language", "prompt": "What connects these four?", "clues": ["Knight", "Knee", "Knife", "Knock"], "correct_connection": "Words with a silent initial K", "distractors": ["Words that are palindromes", "Names of chess pieces", "Words that all rhyme"], "explanation": "In standard English pronunciation, the initial K is silent in all four words."}, {"external_key": "discovery-20260929-thirty-days", "category": "general", "prompt": "What connects these four?", "clues": ["April", "June", "September", "November"], "correct_connection": "Months with exactly 30 days", "distractors": ["Months with 31 days", "Months whose length changes in leap years", "The first four months of the year"], "explanation": "Each of these months always has 30 days in the Gregorian calendar. Leap years change February."}, {"external_key": "discovery-20260929-intercardinal", "category": "general", "prompt": "What connects these four?", "clues": ["Northeast", "Southeast", "Southwest", "Northwest"], "correct_connection": "The four intercardinal compass directions", "distractors": ["The four cardinal compass directions", "Lines of latitude", "Time zones"], "explanation": "These directions lie halfway between the cardinal directions north, east, south and west."}]}$payload$::jsonb; r jsonb; v_id uuid; pos integer; choice text; checked jsonb;
begin
  for r in select value from jsonb_array_elements(b->'routes') loop
    checked := public.brainilab_number_route_solutions(array(select jsonb_array_elements_text(r->'numbers')::integer),(r->>'target')::integer);
    if (checked->>'count')::integer<>1 or checked->'solution'<>r->'solution' then raise exception 'Invalid route %',r->>'external_key'; end if;
    if exists(select 1 from public.number_route_puzzles where numbers=array(select jsonb_array_elements_text(r->'numbers')::integer) and target=(r->>'target')::integer and external_key<>r->>'external_key') then raise exception 'Duplicate route'; end if;
    insert into public.number_route_puzzles(external_key,category,numbers,target,solution,is_active)
    values(r->>'external_key','math',array(select jsonb_array_elements_text(r->'numbers')::integer),(r->>'target')::integer,array(select jsonb_array_elements_text(r->'solution')),true) on conflict(external_key) do nothing;
  end loop;
  for r in select value from jsonb_array_elements(b->'connections') loop
    if jsonb_array_length(r->'clues')<>4 or jsonb_array_length(r->'distractors')<>3 or length(r->>'explanation')<10 then raise exception 'Incomplete clues'; end if;
    if (select count(distinct lower(value)) from jsonb_array_elements_text((r->'distractors')||jsonb_build_array(r->>'correct_connection')))<>4 then raise exception 'Duplicate choices'; end if;
    if exists(select 1 from jsonb_array_elements_text(r->'clues') where lower(value)=lower(r->>'correct_connection')) then raise exception 'Answer in clue'; end if;
    insert into public.connections_puzzles(external_key,category,prompt,clues,explanation,is_active)
    values(r->>'external_key',r->>'category',r->>'prompt',r->'clues',r->>'explanation',true) on conflict(external_key) do nothing returning id into v_id;
    if v_id is not null then
      insert into public.connections_choices(puzzle_id,position,choice_text,is_correct) values(v_id,1,r->>'correct_connection',true);
      pos:=2;
      for choice in select jsonb_array_elements_text(r->'distractors') loop
        insert into public.connections_choices(puzzle_id,position,choice_text,is_correct) values(v_id,pos,choice,false);pos:=pos+1;
      end loop;
    end if;
  end loop;
  if (select count(*) from public.number_route_puzzles where external_key like 'discovery-20260929-route-%')<>60 then raise exception 'Route count mismatch'; end if;
  if (select count(*) from public.connections_puzzles where external_key like 'discovery-20260929-%')<>24 then raise exception 'Connections count mismatch'; end if;
end $batch$;
commit;
select 'number_route' as pool,count(*) as added from public.number_route_puzzles where external_key like 'discovery-20260929-route-%'
union all select 'connections',count(*) from public.connections_puzzles where external_key like 'discovery-20260929-%';
